-- Contenu de fin de jeu : chapitres de campagne 16 à 20 (étages 151-200)
-- et étages 11 à 15 des quatre tours, calibrés au simulateur vers une équipe
-- de 3 légendaires n70 en équipement légendaire (campaign.definitions.ts,
-- tower.definitions.ts, prisma/seed/balance-calibration.ts).
--
-- Rien d'existant n'est modifié : les 150 étages de campagne et les étages
-- 1 à 10 des tours gardent leurs valeurs (legacy-content-frozen.test.ts). Le
-- déblocage suit la progression stockée : un joueur qui a battu 15-10 voit
-- 16-1, un joueur à l'étage 10 d'une tour voit le 11.
--
-- Migration de DONNÉES (le déploiement ne seede jamais), générée depuis les
-- définitions. Idempotente : insertion seulement si la ligne manque.

ON CONFLICT (chapter, "index") DO NOTHING;

ON CONFLICT (element, "index") DO NOTHING;

WITH r AS (
  SELECT gen_random_uuid()::text, 15, 400, 0, 'RARE'::"CardRarity"
  WHERE NOT EXISTS (SELECT 1 FROM "Achievement" WHERE key = 'chapter_reached_17')
  RETURNING id
)
SELECT gen_random_uuid()::text, 'chapter_reached_17', 'Éclipse', 'Eclipse', 'Atteindre le chapitre 17.', 'Reach chapter 17.', 'campaign', 3, false, '{"type":"CAMPAIGN_CHAPTER_REACHED","threshold":17}'::jsonb, 14, true, r.id
FROM r;

WITH r AS (
  SELECT gen_random_uuid()::text, 30, 800, 0, 'EPIC'::"CardRarity"
  WHERE NOT EXISTS (SELECT 1 FROM "Achievement" WHERE key = 'chapter_reached_20')
  RETURNING id
)
SELECT gen_random_uuid()::text, 'chapter_reached_20', 'Trône du Chaos', 'Throne of Chaos', 'Atteindre le chapitre 20.', 'Reach chapter 20.', 'campaign', 4, false, '{"type":"CAMPAIGN_CHAPTER_REACHED","threshold":20}'::jsonb, 15, true, r.id
FROM r;
